urlset:
{%- for entry in entries %}

      {{ entry.permalink | escape_html | safe }}
      {%- if entry.updated %}
      {{ entry.updated | escape_html | safe }}
      {%- endif %}

  {%- set_global seen = [...seen, entry.permalink] -%}
{%- endfor -%}
{%- set_global links = [] -%}
{%- if data.extra is defined -%}
  {%- if data.extra.nav_links is defined -%}
    {%- set_global links = [...links, ...data.extra.nav_links] -%}
  {%- endif -%}
  {%- if data.extra.footer_links is defined -%}
    {%- set_global links = [...links, ...data.extra.footer_links] -%}
  {%- endif -%}
{%- endif -%}
{%- for link in links -%}
  {%- if link.sitemap is defined and link.sitemap and link.path is defined and link.path -%}
    {# Only local paths: reject protocol-relative URLs and URL schemes. #}
    {%- if not link.path is starting_with(pat="//") and not ":" in link.path -%}
      {%- set trailing_slash = link.path is ending_with(pat="/") -%}
      {%- set url = get_url(path=link.path, trailing_slash=trailing_slash) -%}
      {%- if url not in seen %}

      {{ url | escape_html | safe }}

        {%- set_global seen = [...seen, url] -%}
      {%- endif -%}
    {%- endif -%}
  {%- endif -%}
{%- endfor %}
